const money=n=>new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:0}).format(n)+' Kč';
const LOCATIONS=[{id:'karlin',name:'Karlín',city:'Praha',x:70,y:31,rent:15500,setup:390000,traffic:1050,segment:'Kanceláře',ideal:89},{id:'vinohrady',name:'Vinohrady',city:'Praha',x:70,y:69,rent:13000,setup:310000,traffic:880,segment:'Výběrová káva',ideal:99},{id:'letna',name:'Letná',city:'Praha',x:47,y:23,rent:11000,setup:260000,traffic:750,segment:'Kreativci',ideal:85},{id:'smichov',name:'Smíchov',city:'Praha',x:26,y:76,rent:14000,setup:330000,traffic:980,segment:'Kanceláře',ideal:85},{id:'centrum',name:'Staré Město',city:'Praha',x:46,y:53,rent:21000,setup:460000,traffic:1450,segment:'Turisté',ideal:109},{id:'dejvice',name:'Dejvice',city:'Praha',x:23,y:25,rent:9500,setup:220000,traffic:820,segment:'Studenti',ideal:69},{id:'brno',name:'Brno · Veveří',city:'Brno',x:47,y:38,rent:10000,setup:280000,traffic:950,segment:'Studenti',ideal:79},{id:'brnostred',name:'Brno · Centrum',city:'Brno',x:60,y:66,rent:14000,setup:370000,traffic:1200,segment:'Turisté',ideal:89},{id:'viden',name:'Vídeň · Neubau',city:'Vídeň',x:37,y:40,rent:26000,setup:620000,traffic:1450,segment:'Výběrová káva',ideal:129},{id:'videnstred',name:'Vídeň · Innere Stadt',city:'Vídeň',x:63,y:60,rent:33000,setup:820000,traffic:1850,segment:'Turisté',ideal:149}];
function fresh(){return {version:1,week:1,cash:900000,reputation:48,stores:[{id:'karlin',price:85,staff:3,wage:6500,marketing:1500,quality:68,manager:null,policy:'quality',auto:{staff:true,price:true,marketing:true},last:null}],coffee:{origin:'brazil',roast:2,arabica:80,name:'První světlo',green:180,roasted:45,age:0,auto:true,capacity:100},history:[],logs:[{week:1,text:'Karlín má otevřeno. Tvoje první kavárna čeká na první výsledky.',detail:'Začni nastavením kávy a pravomocí manažera.'}],trust:65,debt:0,loanTaken:false,rival:12,rivalPrice:79,expansionBudget:0,boardCooldown:0,win:false,over:false}};
let state=fresh();
const ORIGINS={brazil:{name:'Brazílie · Cerrado',cost:210,quality:70,taste:'Čokoláda, oříšky',roast:3},colombia:{name:'Kolumbie · Huila',cost:285,quality:82,taste:'Karamel, citrusy',roast:2},ethiopia:{name:'Etiopie · Sidamo',cost:360,quality:93,taste:'Jasmín, bergamot',roast:1}};
const MANAGERS=[{name:'Anna Nováková',skill:90,salary:9500,trait:'Kvalita a tým',initials:'AN'},{name:'David Veselý',skill:78,salary:7200,trait:'Efektivní provoz',initials:'DV'},{name:'Eliška Malá',skill:85,salary:8400,trait:'Hosté a značka',initials:'EM'}];
const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));const round=n=>Math.round(n);const loc=id=>LOCATIONS.find(l=>l.id===id);
function log(text,detail=''){state.logs.unshift({week:state.week,text,detail});state.logs=state.logs.slice(0,60)}
function coffeeQuality(){const c=state.coffee,o=ORIGINS[c.origin];return round(clamp(o.quality-Math.abs(c.roast-o.roast)*7-(100-c.arabica)*.16-Math.max(0,c.age-1)*6,15,99))}
function spend(n){if(state.cash<n)throw Error('Na tento krok nemáš dost hotovosti.');state.cash-=n}
function unlocked(c){return c==='Praha'||c==='Brno'&&state.stores.length>=3||c==='Vídeň'&&state.stores.length>=5&&state.reputation>=65}
function openStore(id){const l=loc(id);if(!l)throw Error('Neznámá lokalita.');if(state.over)throw Error('Tato hra už skončila.');if(state.stores.some(s=>s.id===id))throw Error('Tuhle kavárnu už vlastníš.');if(!unlocked(l.city))throw Error(l.city==='Brno'?'Brno se otevře se třemi kavárnami.':'Vídeň potřebuje pět kaváren a pověst alespoň 65.');if(state.stores.length>=3&&state.expansionBudget<l.setup)throw Error('Board musí schválit expanzní mandát.');spend(l.setup);if(state.stores.length>=3)state.expansionBudget-=l.setup;state.stores.push({id,price:l.ideal,staff:3,wage:6500,marketing:1500,quality:62,manager:null,policy:'quality',auto:{staff:true,price:true,marketing:true},last:null});log('Nová adresa: '+l.name,'Otevření stálo '+money(l.setup)+'. Příští týden začne běžný provoz.')}
function hire(id,index){const s=state.stores.find(s=>s.id===id),m=MANAGERS[index];if(!s||!m)throw Error('Neplatný manažer.');spend(12000);s.manager={...m};log(m.name+' přebírá '+loc(id).name,'Nábor '+money(12000)+', týdenní mzda '+money(m.salary)+'. Pravomoci nastavíš v sekci Lidé.')}
function orderBeans(kg){if(!Number.isInteger(kg)||kg<1||kg>1000)throw Error('Objednávka musí být 1–1 000 kg.');spend(kg*ORIGINS[state.coffee.origin].cost);state.coffee.green+=kg;log('Nakoupeno '+kg+' kg zelené kávy',ORIGINS[state.coffee.origin].name+' · '+money(kg*ORIGINS[state.coffee.origin].cost))}
function roast(kg){if(!Number.isInteger(kg)||kg<1||kg>state.coffee.capacity)throw Error('Pražit lze 1–'+state.coffee.capacity+' kg.');if(state.coffee.green<kg)throw Error('Chybí zelená káva.');spend(kg*55);const c=state.coffee;c.green-=kg;c.roasted+=kg*.84;c.age=0;log('Upraženo '+round(kg*.84)+' kg směsi '+c.name,'Ztráta při pražení 16 %. Náklad na pražení '+money(kg*55)+'.')}
function proposal(type){let votes=[];const recent=state.history.slice(-4),avg=recent.length?recent.reduce((a,h)=>a+h.profit,0)/recent.length:0;const managed=state.stores.filter(s=>s.manager).length;const margin=state.history.at(-1)?.margin||0;const q=coffeeQuality();const cash=state.cash;
if(type==='expansion')votes=[{name:'Petr · finance',yes:cash>=550000&&avg>0,reason:cash<550000?'Hotovost musí být alespoň 550 000 Kč.':avg<=0?'Průměr posledních čtyř týdnů musí být ziskový.':'Hotovost i provozní zisk dávají prostor pro růst.'},{name:'Jana · provoz',yes:managed>=Math.ceil(state.stores.length*.6),reason:managed>=Math.ceil(state.stores.length*.6)?'Alespoň 60 % poboček má manažera.':'Nejdřív obsadíme manažery alespoň 60 % poboček.'},{name:'Lucie · produkt',yes:q>=72&&state.reputation>=50,reason:q<72?'Kvalita směsi musí dosáhnout 72 bodů.':state.reputation<50?'Pověst značky musí dosáhnout 50.':'Káva i značka jsou připravené na další město.'}];
if(type==='roastery')votes=[{name:'Petr · finance',yes:cash>=450000,reason:cash>=450000?'Investici 180 000 Kč pokryjeme s rezervou.':'Požaduji hotovost alespoň 450 000 Kč.'},{name:'Jana · provoz',yes:state.stores.length>=2,reason:state.stores.length>=2?'Dvě a více kaváren využijí vyšší kapacitu.':'Nejdřív potřebujeme alespoň dvě kavárny.'},{name:'Lucie · produkt',yes:q>=65,reason:q>=65?'Vyšší kapacita podpoří naši vlastní kávu.':'Nejdřív zvedneme kvalitu směsi na 65.'}];
if(type==='dividend')votes=[{name:'Petr · finance',yes:cash>=800000&&avg>20000,reason:cash<800000?'Chci hotovost alespoň 800 000 Kč.':avg<=20000?'Průměrný zisk musí být nad 20 000 Kč.':'Firma má dostatečný zisk i rezervu.'},{name:'Jana · provoz',yes:state.stores.every(s=>s.quality>=65),reason:state.stores.every(s=>s.quality>=65)?'Všechny provozy jsou v dobré kondici.':'Některé kavárny potřebují péči: kvalita pod 65.'},{name:'Lucie · produkt',yes:margin>=.2,reason:margin>=.2?'Marže alespoň 20 % dovolí výplatu.':'Nejdřív chci poslední provozní marži alespoň 20 %.'}];
return {votes,passed:votes.filter(v=>v.yes).length>=2,avg};}
function board(type){if(state.week<state.boardCooldown)throw Error('Další zasedání lze svolat v týdnu '+state.boardCooldown+'.');if(!['expansion','roastery','dividend'].includes(type))throw Error('Neplatný návrh.');if(type==='roastery'&&state.coffee.capacity>=250)throw Error('Pražírna už je rozšířená.');const p=proposal(type);state.boardCooldown=state.week+3;if(p.passed){if(type==='expansion'){state.expansionBudget=1500000;log('Board schválil expanzní mandát','Otevření dalších kaváren až do souhrnné investice 1 500 000 Kč. Nejde o nové peníze; platíš ze své hotovosti.')}if(type==='roastery'){spend(180000);state.coffee.capacity=250;log('Board schválil větší pražírnu','Kapacita vzrostla na 250 kg zelené kávy týdně. Investice 180 000 Kč.')}if(type==='dividend'){spend(100000);state.dividends=(state.dividends||0)+100000;log('Výplata dividendy schválena','100 000 Kč přesunuto z firmy do tvého osobního majetku.')}}else{log('Board návrh zamítl',p.votes.filter(v=>!v.yes).map(v=>v.reason).join(' '))}return p}
function autoManager(s){const l=loc(s.id),m=s.manager,decisions=[];if(!m)return decisions;const target=Math.ceil(l.traffic/350),buffer=state.cash>100000;const maxSpend=s.policy==='profit'?2200:s.policy==='growth'?5000:3500;
if(s.auto.staff){const optimal=clamp(target,2,5);if(s.staff!==optimal&&buffer){decisions.push('Tým '+s.staff+' → '+optimal+': pokrytí odhadované poptávky.');s.staff=optimal}}
if(s.auto.price){const ideal=l.ideal+(s.policy==='quality'?5:s.policy==='profit'?10:-5);const step=clamp(ideal-s.price,-5,5);if(step){s.price+=step;decisions.push('Cena '+money(s.price)+': '+(s.policy==='growth'?'podpora získávání hostů.':s.policy==='profit'?'vyšší marže při místní poptávce.':'pozice výběrové značky.'))}}
if(s.auto.marketing){const targetMarketing=buffer?maxSpend:0;if(s.marketing!==targetMarketing){s.marketing=targetMarketing;decisions.push('Marketing '+money(s.marketing)+': '+(buffer?'v rámci schváleného cíle.':'pozastaven kvůli nízké hotovosti.'))}}
return decisions}
function nextWeek(){if(state.over)throw Error('Hra skončila. Začni novou hru nebo načti uloženou.');let events=[];const week=state.week;let demandFactor=1;if(week%9===0){demandFactor=1.15;events.push('Městský festival: poptávka tento týden +15 %.')}else if(week%7===0){demandFactor=.85;events.push('Deštivý týden: návštěvnost −15 %.')}
const c=state.coffee;const decisions=new Map;state.stores.forEach(s=>decisions.set(s.id,autoManager(s)));const needed=state.stores.reduce((a,s)=>a+loc(s.id).traffic*.019,0);let supplySpend=0;
if(c.auto){const want=clamp(Math.ceil((needed*1.25-c.roasted)/.84),0,c.capacity);const missing=Math.max(0,want-c.green);const buyCost=missing*ORIGINS[c.origin].cost;const roasting=want*55;const payrollReserve=state.stores.reduce((a,s)=>a+loc(s.id).rent+s.staff*s.wage+(s.manager?.salary||0),0);if(want>0&&state.cash-buyCost-roasting>payrollReserve){c.green+=missing;c.green-=want;c.roasted+=want*.84;c.age=0;supplySpend=buyCost+roasting;state.cash-=supplySpend}}
const quality=coffeeQuality(),freshness=clamp(1-Math.max(0,c.age-1)*.09,.4,1);let revenue=0,costs=0,cups=0,consumed=0;const startRoasted=c.roasted;
for(const s of state.stores){const l=loc(s.id),m=s.manager;const morale=clamp(50+(s.wage-6500)/130+(m?(m.skill-60)*.6:0),20,95);const service=clamp(s.staff*350/l.traffic,0.4,1.12);const management=m?.skill/100||.58;const targetQ=quality*.55+morale*.2+management*25; s.quality=round(s.quality*.55+targetQ*.45);
const appeal=clamp(1+(s.quality-65)/100+(state.reputation-50)/130+Math.sqrt(s.marketing/1500)*.13-.10,.3,1.9);const priceFactor=clamp(1-(s.price-l.ideal)/l.ideal*1.5,.25,1.5);const competition=clamp(1-state.rival*.003-(state.rivalPrice<s.price? .025:0),.7,1);const demand=round(l.traffic*appeal*priceFactor*competition*demandFactor*freshness);const capacity=s.staff*370;const potential=Math.min(demand,capacity);const allocation=needed?startRoasted*(l.traffic*.019/needed):0;const served=Math.min(potential,Math.floor(allocation/.018));const used=served*.018;consumed+=used;const sales=served*s.price;const wages=s.staff*s.wage;const manager=m?.salary||0;const rent=l.rent;const ingredients=served*13;const overhead=3200;const rawCost=used/.84*ORIGINS[c.origin].cost;const roastCost=used/.84*55;const allCost=wages+manager+rent+ingredients+overhead+s.marketing;const profit=sales-allCost-rawCost-roastCost;
const lost=Math.max(0,demand-served);let reason=served<potential?'Došla pražená káva; hosty nelze obsloužit.':demand>capacity?'Tým nestíhá všechny hosty.':s.price>l.ideal+15?'Cena je vysoko nad očekáváním této čtvrti.':s.quality<65?'Kvalita a služba snižují návratnost hostů.':'Kapacita, cena a kvalita odpovídají místní poptávce.';
s.last={revenue:sales,cost:allCost+rawCost+roastCost,profit:round(profit),served,lost,quality:s.quality,morale:round(morale),used:round(used*10)/10,reason,decisions:decisions.get(s.id),detail:{wages,manager,rent,ingredients,overhead,marketing:s.marketing,coffee:round(rawCost+roastCost)}};revenue+=sales;costs+=allCost;cups+=served;}
c.roasted=Math.max(0,c.roasted-consumed);c.age++;state.cash+=revenue-costs;const interest=state.debt*.002;state.cash-=interest;const inventoryCost=consumed/.84*(ORIGINS[c.origin].cost+55);const profit=round(revenue-costs-inventoryCost-interest);const avgQ=state.stores.reduce((a,s)=>a+s.quality,0)/state.stores.length;const shortage=state.stores.some(s=>s.last.lost>loc(s.id).traffic*.3);state.reputation=round(clamp(state.reputation+(avgQ-65)*.09+(shortage?-2:1),5,99));state.rival=clamp(state.rival+(week%4===0?2:0),12,36);state.rivalPrice=week%8<3?74:82;
state.history.push({week,revenue:round(revenue),costs:round(costs),profit,cups,coffee:round(inventoryCost),interest:round(interest),supplySpend:round(supplySpend),cash:round(state.cash),margin:revenue?profit/revenue:0,event:events.join(' ')});if(state.history.length>104)state.history.shift();log('Týden '+week+': '+money(profit)+' provozního výsledku',cups+' šálků · '+(events.join(' ')||'Běžný týden.')+(shortage?' Některé pobočky ztratily hosty kvůli kapacitě nebo zásobám.':''));state.week++;state.trust=round(clamp(65+(state.reputation-50)*.5+(profit>0?8:-8),15,95));
if(state.cash<0){state.over=true;log('Firma se dostala do platební neschopnosti.','Hotovost klesla pod nulu. V nové hře drž větší rezervu a zkontroluj zásoby a mzdy.')}if(!state.win&&state.stores.length>=6&&state.reputation>=75&&state.history.slice(-4).length===4&&state.history.slice(-4).every(h=>h.profit>0)){state.win=true;log('Milník splněn: vlastní kávové impérium!','Šest kaváren, pověst 75+ a čtyři ziskové týdny. Můžeš pokračovat a ovládnout další lokality.')}return state.history.at(-1)}
function takeLoan(){if(state.loanTaken)throw Error('Rozvojový úvěr už jsi využil.');state.cash+=400000;state.debt+=400000;state.loanTaken=true;log('Rozvojový úvěr: 400 000 Kč','Týdenní úrok 0,2 % z nesplacené jistiny. Splácení je dobrovolné, úrok běží každý týden.')}
function repay(){if(state.debt<=0)throw Error('Nemáš žádný dluh.');const payment=Math.min(state.debt,100000);spend(payment);state.debt-=payment;log('Splaceno '+money(payment)+' z úvěru.')}
